// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(target != address(c));

        Reverter reverter = new Reverter();
        address payable adversarial = payable(address(reverter));

        vm.deal(address(c), amount);

        uint256 balanceBefore = address(c).balance;

        bool ok = true;
        try c.sendMoney(adversarial, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = address(c).balance;

        assertTrue(
            (ok && balanceAfter == balanceBefore - amount) || (!ok && balanceAfter == balanceBefore)
        );
    }
}

contract Reverter {
    fallback() external payable {
        revert("Reverter: forced failure");
    }
}
